export const ENTITY_DETAILS: Readonly<Record<string, EntityDetail>> = Object.fromEntries(
  ENTITIES.map((entity) => [entity.id, entity]),
);

export function getEntityDetail(id: string): EntityDetail | null {
  return Object.prototype.hasOwnProperty.call(ENTITY_DETAILS, id) ? ENTITY_DETAILS[id] : null;
}
